import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    key_counts = Counter()
    for entry in data:
        try:
            dictionary = ast.literal_eval(entry) if isinstance(entry, str) else entry
            if isinstance(dictionary, dict):
                key_counts.update(dictionary.keys())
        except (ValueError, SyntaxError):
            continue
    return key_counts

