import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    all_words = []

    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as json_file:
                try:
                    data = json.load(json_file)
                    text = data.get('text', '')
                    text = ''.join(c if c.isalnum() or c.isspace() else ' ' for c in text).lower()
                    all_words.extend(text.split())
                except json.JSONDecodeError:
                    continue

    word_counts = Counter(all_words)
    return word_counts.most_common(word_count)

import os
import json
from collections import Counter
import re
import string
def task_func(json_dir_path, word_count):
    word_counts = Counter()
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as file:
                try:
                    data = json.load(file)
                    text = data.get('text', '').lower()
                    text = re.sub('[^\sa-zA-Z0-9]', '', text).translate({ord(c): None for c in string.punctuation})
                    word_counts.update(text.split())
                except json.JSONDecodeError:
                    continue
    return word_counts.most_common(word_count)

import cgi
import http.server
import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}
def task_func():
    class PostRequestHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type = self.headers.get('content-type')
            if content_type != 'application/json':
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {'status': 'error', 'message': 'Content-Type header is not application/json'}
                self.wfile.write(json.dumps(response).encode('utf-8'))
                return

            content_length = int(self.headers.get('content-length', 0))
            body = self.rfile.read(content_length).decode('utf-8')
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {'status': 'error', 'message': 'Invalid JSON'}
                self.wfile.write(json.dumps(response).encode('utf-8'))
                return

            if 'data' not in data:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {'status': 'error', 'message': 'No data key in request'}
                self.wfile.write(json.dumps(response).encode('utf-8'))
                return

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', len(json.dumps(SUCCESS_RESPONSE).encode('utf-8')))
            self.end_headers()
            self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode('utf-8'))

